395					if rec.Code != http.StatusCreated && rec.Code != http.StatusOK {
396						t.Errorf("register = %d", rec.Code)
397						return
398					}
399					var resp registerResponse
400					if err := json.Unmarshal(rec.Body.Bytes(), &resp); err != nil {
401						t.Errorf("register response not JSON: %v", err)
402						return
403					}
404					hdr := map[string]string{leaseHeader: resp.LeaseToken}
405					if rec := do(t, h, http.MethodPost, base+"/heartbeat", "", hdr); rec.Code != http.StatusNoContent && rec.Code != http.StatusConflict && rec.Code != http.StatusNotFound {
406						t.Errorf("heartbeat = %d", rec.Code)
407					}
408					if rec := do(t, h, http.MethodGet, "/v1/discovery/svc", "", nil); rec.Code != http.StatusOK {
409						t.Errorf("discovery = %d", rec.Code)
410					}
411					if rec := do(t, h, http.MethodDelete, base, "", hdr); rec.Code != http.StatusNoContent && rec.Code != http.StatusNotFound && rec.Code != http.StatusConflict {
412						t.Errorf("delete = %d", rec.Code)
413					}
414				}
415			}(i)
416		}
417		wg.Wait()
418	}
