	rec := getResolve(t, h, "/v1/resolve/svc?key=k1")
	if rec.Code != http.StatusServiceUnavailable || errorCode(t, rec) != "no_available_instance" {
		t.Fatalf("after expiry = %d (%s), want 503", rec.Code, errorCode(t, rec))
	}
